                let lo = vreinterpretq_u16_u8(vreinterpretq_u8_s8(a.0));
                let hi = vreinterpretq_u16_u8(vreinterpretq_u8_s8(a.1));
                let pairs_lo = vshrn_n_u16::<7>(lo);
                let pairs_hi = vshrn_n_u16::<7>(hi);
